package com.primehr.security;
import com.primehr.integration.administrative.*; import org.junit.jupiter.api.*; import org.springframework.security.access.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class Phase5dPermissionGuardTest {private final AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);
 @Test void evaluationPolicyRequiresExactPublishAndAgencyScope(){RspEvaluationPolicyPermissionGuard guard=new RspEvaluationPolicyPermissionGuard(client);when(client.resolve(eq(RspEvaluationPolicyPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(RspEvaluationPolicyPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(RspEvaluationPolicyPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).doesNotThrowAnyException();}
 @Test void candidateActionsRemainIndependent(){RspCandidateEvaluationPermissionGuard guard=new RspCandidateEvaluationPermissionGuard(client);EffectiveFeaturePermission p=new EffectiveFeaturePermission(RspCandidateEvaluationPermissionGuard.FEATURE,false,true,true,true,false,false,true,false,true,false,false,PermissionDataScope.AGENCY_WIDE);when(client.resolve(eq(RspCandidateEvaluationPermissionGuard.FEATURE),anyString())).thenReturn(p);assertThatCode(()->guard.require(PrimeHrAction.ASSESS,"Bearer token")).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(PrimeHrAction.VALIDATE,"Bearer token")).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->guard.require(PrimeHrAction.FINALIZE,"Bearer token")).isInstanceOf(AccessDeniedException.class);}
 private static EffectiveFeaturePermission permission(boolean access,boolean publish,PermissionDataScope scope){return new EffectiveFeaturePermission("feature",false,access,false,false,false,publish,false,false,false,false,false,scope);}}
